  `outline_data` json NULL COMMENT '结构化大纲数据（JSON）',
  `char_profiles_json` json NULL COMMENT '结构化人物卡（JSON）',
  `world_setting` json NULL COMMENT '世界观/设定（JSON）',
  `plot_hooks` json NULL COMMENT '伏笔清单（JSON）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user`(`user_id`) USING BTREE,
  CONSTRAINT `fk_work_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '创作作品' ROW_FORMAT = Dynamic;

